					if curPos.col+1 < int16(n) && grid[curPos.row][curPos.col+1] == '1' {
						q.PushBack(Pos{curPos.row, curPos.col + 1})
						grid[curPos.row][curPos.col+1] = '0'
					}
				}
			}
		}
	}
	return numIsland
}

